    uint8_t *storage;
    size_t capacity;
    size_t head;   /* write position (next free slot) */
    size_t tail;   /* read position  (oldest byte) */
    size_t count;  /* number of bytes currently stored */
};

ringbuf_t *rb_create(size_t capacity)
{
    ringbuf_t *rb = NULL;

    if (capacity == 0)
        return NULL;

    rb = malloc(sizeof(*rb));
    if (!rb)
        return NULL;

    rb->storage = malloc(capacity);
    if (!rb->storage) {
        free(rb);
        return NULL;
    }

    rb->capacity  = capacity;
    rb->head      = 0;
    rb->tail      = 0;
    rb->count     = 0;

    return rb;
}

void rb_destroy(ringbuf_t *rb)
{
    if (!rb)
        return;
    free(rb->storage);
    free(rb);
}

size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len)
{
    size_t written;

    if (!rb || !data || len == 0)
        return 0;

    /* bytes available for writing = capacity - count */
    written = len;
    if (written > rb->capacity - rb->count)
        written = rb->capacity - rb->count;

    if (written == 0)
        return 0;

    /* first segment: from head to end of storage, or as much as needed */
    {
        size_t seg1 = rb->capacity - rb->head;
        size_t cnt1 = written < seg1 ? written : seg1;
        memcpy(rb->storage + rb->head, data, cnt1);
        rb->head = (rb->head + cnt1) % rb->capacity;
        written -= cnt1;
        data    += cnt1;
    }

    /* second segment (wrap-around), only if more remains */
    if (written > 0) {
        memcpy(rb->storage + rb->head, data, written);
        rb->head = (rb->head + written) % rb->capacity;
    }

    rb->count += (len < rb->capacity - rb->count + (size_t)(written)) ? /* keep simple */ 0 : 0;
