    if (!rb->storage) {
        free(rb);
        return NULL;    }

    rb->capacity  = capacity;
    rb->head      = 0;
    rb->tail      = 0;
    rb->count     = 0;

    return rb;
}

void rb_destroy(ringbuf_t *rb)
{
    if (!rb)
        return;
    free(rb->storage);
    free(rb);
}

size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len)
{
    size_t avail, written, cnt1;

    if (!rb || !data || len == 0)
        return 0;

    avail = rb->capacity - rb->count;
    if (avail == 0)
        return 0;

    written = len < avail ? len : avail;

    /* First contiguous segment */
    cnt1 = rb->capacity - rb->head;
    if (written > cnt1)
        written = cnt1;

    memcpy(rb->storage + rb->head, data, written);
    rb->head = (rb->head + written) % rb->capacity;
    rb->count += written;

    /* Wrap-around segment */
    if (written < avail) {
        size_t remaining = len > (size_t)(avail - 1) ? avail : len;
        memcpy(rb->storage, data + written, remaining);
        rb->head = (rb->head + remaining) % rb->capacity;
        rb->count += remaining;
    }

    return cnt1 >= len ? len : cnt1;
