    space = rb->capacity - rb->count;
    if (space == 0)
        return 0;

    /* Clamp to what was requested and what fits.                     */
    amt   = len < space ? len : space;

    /* Decide whether the first chunk wraps around the end of storage.*/
    {
        size_t head_end = rb->capacity - rb->head;

        if (amt <= head_end) {
            memcpy(rb->storage + rb->head, data, amt);
        } else {
            memcpy(rb->storage + rb->head, data, head_end);
