struct ringbuf {
    uint8_t *storage;
    size_t capacity;
    size_t head;   /* next free slot for writing         */
    size_t tail;   /* oldest byte (next position to read)  */
    size_t count;  /* bytes currently in the buffer        */
};

/* ------------------------------------------------------------------ */

ringbuf_t *rb_create(size_t capacity)
{
    ringbuf_t *rb;

    if (capacity == 0)
        return NULL;

    rb = malloc(sizeof(*rb));
    if (!rb)
        return NULL;

    rb->storage = malloc(capacity);
    if (!rb->storage) {
        free(rb);
        return NULL;
    }

    rb->capacity  = capacity;
    rb->head      = 0;
    rb->tail      = 0;
    rb->count     = 0;

    return rb;
}

/* ------------------------------------------------------------------ */

void rb_destroy(ringbuf_t *rb)
{
    if (!rb)
        return;
    free(rb->storage);
    free(rb);
}

/* Write up to `len` bytes to the buffer (oldest first).
   Returns number of bytes actually written.                     */

size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len)
{
    size_t space, amt;
    size_t head_end;

    if (!rb || !data || len == 0)
        return 0;

    space = rb->capacity - rb->count;
    if (space == 0)
        return 0;

    amt   = len < space ? len : space;
    head_end = rb->capacity - rb->head;

    /* First contiguous write */
    if (amt <= head_end) {
        memcpy(rb->storage + rb->head, data, amt);
    } else {
        memcpy(rb->storage + rb->head, data, head_end);
        /* Wrapped copy around storage end -> start */
        memcpy(rb->storage, data + head_end, amt - head_end);
    }

    rb->head      = (rb->head + amt) % rb->capacity;
    rb->count    += amt;
    return amt;
}

/* ------------------------------------------------------------------ */

size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len)
{
    size_t avail, amt;
    size_t tail_end;

    if (!rb || !out  || len == 0 || rb->count == 0)
        return 0;

    avail = rb->count < len ? rb->count : len;
    tail_end  = rb->capacity - rb->tail;

    /* First contiguous read */
    if (avail <= tail_end) {
        memcpy(out, rb->storage + rb->tail, avail);
    } else {
        memcpy(out,          rb->storage + rb->tail, tail_end);
        memcpy(out + tail_end, rb->storage, avail - tail_end);
    }

    rb->tail      = (rb->tail + avail) % rb->capacity;
    rb->count    -= avail;
    return avail;
}

/* ------------------------------------------------------------------ */

size_t rb_peek(const ringbuf_t *rb_in, uint8_t *out, size_t len)
{
    const struct ringbuf *rb = (const struct ringbuf *)rb_in;
    size_t avail, amt;
    size_t tail_end;

    if (!rb || !out   || len == 0 || rb->count == 0)
        return 0;

    avail = rb->count < len ? rb->count : len;
    tail_end  = rb->capacity - rb->tail;

    /* First chunk */
    if (avail <= tail_end) {
        memcpy(out, rb->storage + rb->tail, avail);
    } else {
        memcpy(out,          rb->storage + rb->tail, tail_end);
        memcpy(out + tail_end, rb->storage, avail - tail_end);
    }

    return avail;
}

/* ------------------------------------------------------------------ */

size_t rb_size(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->count;
}

/* ------------------------------------------------------------------ */

size_t rb_capacity(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->capacity;
}

/* ------------------------------------------------------------------ */

void rb_clear(ringbuf_t *rb)
{
    if (!rb)
        return;
    rb->head = 0;
    rb->tail = 0;
    rb->count = 0;
}

#include <stdio.h>
#include <string.h>
#include <assert.h>
#include "ringbuf.h"

#define TEST(cond, msg) do { \
    if (!(cond)) { printf("FAIL: %s\n", msg); return 1; } \
} while(0)

int main(void)
{
    ringbuf_t *rb;

    /* --- rb_create ------------------------------------------------ */
    rb = rb_create(0);
    TEST(rb == NULL, "create with 0 capacity");

    rb = rb_create(8);
    TEST(rb != NULL, "create valid");

    /* --- rb_capacity / rb_size ------------------------------------ */
    TEST(rb_capacity(rb) == 8, "capacity after create");
    TEST(rb_size(rb)    == 0, "size after create");

    /* --- rb_clear ------------------------------------------------- */
    {
        uint8_t data[4] = {1,2,3,4};
        rb_write(rb, data, 4);
        TEST(rb_size(rb) == 4, "size after write 4 bytes");
        rb_clear(rb);
        TEST(rb_size(rb)    == 0, "size after clear");
        TEST(rb_capacity(rb) == 8, "capacity after clear");
    }

    /* --- rb_write / rb_read (basic loopback) ---------------------- */
    {
        uint8_t input[16];
        uint8_t output[16];
        size_t n;

        for (int i = 0; i < 16; i++)
            input[i] = (uint8_t)i;

        /* Write 8 bytes into 8-capacity buffer */
        TEST(rb_write(rb, input, 8) == 8, "write 8 of 8");
        TEST(rb_size(rb)       == 8,     "size is 8 after write");
        TEST(rb_write(rb, input+8, 1) == 0, "write more when full returns 0");

        TEST(rb_capacity(rb)       == 8,  "capacity stable");

        /* Read back */
        n = rb_read(rb, output, 16);
        TEST(n         == 8,  "read 8 of 8 available");
        TEST(memcmp(input, output, 8) == 0, "loopback data matches");
        TEST(rb_size(rb)       == 0,     "size is 0 after read");

        n = rb_read(rb, output, 1);
        TEST(n == 0, "read when empty returns 0");
    }

    /* --- ring-buffer wrap-around ---------------------------------- */
    {
        uint8_t out[4];
        /* Fill up */
        for (int i = 0; i < 8; i++)
            rb_write(rb, &i, 1);

        /* Read 7 bytes (not the whole buffer) */
        TEST(rb_read(rb, out, 7) == 7, "read 7 of 8");

        /* Now one slot is free; write 4 more so data wraps around storage end */
        rb_write(rb, (uint8_t[]){100,101,102,103}, 4);

        /* Read everything – the tail crosses the boundary */
        TEST(rb_read(rb, out, 4) == 4, "read remaining wrapped bytes");
        TEST(out[0] == 7 && out[1] == 100 && out[2] == 101 && out[3] == 102, "wrap-around read order");

        /* The last byte (103) stays; clear and verify buffer is drained */
        rb_clear(rb);
    }

    /* --- partial write (doesn't fit fully) ------------------------ */
    {
        uint8_t input[8] = {99};
        size_t n;

        for (int i = 0; i < 6; i++)      /* fill 6 of 8 slots        */
            rb_write(rb, &i, 1);
        TEST(rb_size(rb) == 6, "filled 6");

        /* request write of 8 but only 2 bytes fit */
        memset(input, 0xCC, sizeof(input));
        n = rb_write(rb, input, 8);
        TEST(n     == 2, partial write returns count");
        TEST(rb_size(rb) == 8, "buffer is full after partial write");

        /* drain everything to verify the partial data */
        memset(input, 0, sizeof(input));
        n = rb_read(rb, input, 16);
        TEST(n         == 8,  "read back all 8");
        /* last two bytes should be our partial write (0xCC) */
        TEST(input[6] == 99 && input[7] == 99, "partial write data intact");   }

    /* --- rb_peek -------------------------------------------------- */
    {
        uint8_t peek_out[3];

        memset(rb, 0, sizeof(*rb));          /* clear first */
        for (int i = 0; i < 5; i++)
            rb_write(rb, &i, 1);              0,1,2, ... */

        TEST(rb_peek(rb, peek_out, 3) == 3, "peek 3 bytes");
        TEST(peek_out[0] == 0 && peek_out[1]== 1 && peek_out[2]== 2, "peeked values right");

        /* peek should NOT change state */
        TEST(rb_size(rb) == 5, "size unchanged after peek");

        /* peek past EOF */
        TEST(rb_peek(rb, peek_out, 10) == 5, "peek clamped to size");
    }

    /* --- NULL safety ---------------------------------------------- */
    rb_destroy(NULL);
    TEST(rb_size(NULL)     == 0, "rb_size(NULL)        = 0");
    TEST(rb_capacity(NULL) == 0, "rb_capacity(NULL)    = 0");
    TEST(rb_write(NULL, NULL, 0)   == 0, "rb_write(NULL)       = 0");
    TEST(rb_read(NULL,  NULL, 0)   == 0, "rb_read (NULL)       = 0");

    rb_destroy(rb);

    printf("ALL TESTS PASSED\n");
    return 0;
}

